# Publish this repo's rules and skills into user-level agent config folders.
# Additive: existing non-link files/dirs are left untouched; our own links and
# generated files are refreshed. Safe to re-run anytime (e.g. after `git pull`).
#
# Run from an elevated PowerShell (Administrator) or with Developer Mode enabled
# so that creating symlinks is permitted.
$ErrorActionPreference = 'Stop'

$RepoRoot = Split-Path -Parent $PSScriptRoot
$Src = Join-Path $RepoRoot '.claude'
$ClaudeDest = Join-Path $HOME '.claude'
$CopilotSkillsDest = Join-Path $HOME '.copilot\skills'
$GeneratedMarker = 'Generated by ChekTek/ai scripts/update-config'

if ($env:COPILOT_USER_PROMPTS_DIR) {
    $CopilotPromptsDest = $env:COPILOT_USER_PROMPTS_DIR
}
elseif ($env:VSCODE_USER_PROMPTS_FOLDER) {
    $CopilotPromptsDest = $env:VSCODE_USER_PROMPTS_FOLDER
}
else {
    $CopilotPromptsDest = Join-Path $env:APPDATA 'Code\User\prompts'
}

function Link-Kind {
    param(
        [string] $Dest,
        [string] $Label,
        [string] $Kind
    )

    $destKind = Join-Path $Dest $Kind
    New-Item -ItemType Directory -Force $destKind | Out-Null

    Get-ChildItem (Join-Path $Src $Kind) | ForEach-Object {
        $target = Join-Path $destKind $_.Name
        $existing = Get-Item -LiteralPath $target -Force -ErrorAction SilentlyContinue

        if ($existing -and -not $existing.LinkType) {
            Write-Host "skip existing: $Label/$Kind/$($_.Name)"
        }
        else {
            if ($existing) { Remove-Item -LiteralPath $target -Force -Recurse }
            New-Item -ItemType SymbolicLink -Path $target -Target $_.FullName | Out-Null
            Write-Host "linked: $Label/$Kind/$($_.Name)"
        }
    }
}

function Test-GeneratedFileWritable {
    param([string] $Target)

    if (-not (Test-Path -LiteralPath $Target)) { return $true }
    return [bool](Select-String -LiteralPath $Target -Pattern $GeneratedMarker -SimpleMatch -Quiet)
}

function Write-GeneratedFile {
    param(
        [string] $Target,
        [string[]] $Lines,
        [string] $Label
    )

    if (-not (Test-GeneratedFileWritable $Target)) {
        Write-Host "skip existing: $Label"
        return
    }

    New-Item -ItemType Directory -Force (Split-Path -Parent $Target) | Out-Null
    $content = ($Lines -join [Environment]::NewLine) + [Environment]::NewLine
    Set-Content -LiteralPath $Target -Value $content -NoNewline -Encoding UTF8
    Write-Host "generated: $Label"
}

function Convert-RuleToInstruction {
    param([System.IO.FileInfo] $Rule)

    $rulesRoot = Join-Path $Src 'rules'
    $rulesRootPrefix = $rulesRoot.TrimEnd('\', '/') + [System.IO.Path]::DirectorySeparatorChar
    if ($Rule.FullName.StartsWith($rulesRootPrefix, [System.StringComparison]::OrdinalIgnoreCase)) {
        $relative = $Rule.FullName.Substring($rulesRootPrefix.Length)
    }
    else {
        $relative = $Rule.Name
    }
    $name = [System.IO.Path]::ChangeExtension($relative, $null).Replace('\', '-').Replace('/', '-')
    $target = Join-Path $CopilotPromptsDest "$name.instructions.md"
    $lines = Get-Content -LiteralPath $Rule.FullName
    $descriptions = @()
    $paths = @()
    $bodyStart = 0
    $inPaths = $false

    for ($i = 1; $i -lt $lines.Count; $i++) {
        $line = $lines[$i]

        if ($line -eq '---') {
            $bodyStart = $i + 1
            break
        }

        if ($line -match '^description:') {
            $descriptions += $line
            $inPaths = $false
            continue
        }

        if ($line -match '^paths:\s*$') {
            $inPaths = $true
            continue
        }

        if ($inPaths -and $line -match '^\s*-\s*(.+)$') {
            $paths += $Matches[1]
            continue
        }

        $inPaths = $false
    }

    $output = @('---')
    $output += $descriptions
    $output += "name: `"$name`""

    if ($paths.Count -eq 1) {
        $output += "applyTo: $($paths[0])"
    }
    elseif ($paths.Count -gt 1) {
        $output += 'applyTo:'
        $output += ($paths | ForEach-Object { "    - $_" })
    }

    $output += '---'
    $output += "<!-- $GeneratedMarker from .claude/rules/$relative -->"
    $output += ''

    if ($bodyStart -lt $lines.Count) {
        $output += $lines[$bodyStart..($lines.Count - 1)]
    }

    Write-GeneratedFile $target $output "copilot instructions/$name.instructions.md"
}

function Convert-SkillToPrompt {
    param([System.IO.DirectoryInfo] $SkillDir)

    $source = Join-Path $SkillDir.FullName 'SKILL.md'
    if (-not (Test-Path -LiteralPath $source)) { return }

    $name = $SkillDir.Name
    $target = Join-Path $CopilotPromptsDest "$name.prompt.md"
    $lines = Get-Content -LiteralPath $source
    $fields = @()
    $hasName = $false
    $bodyStart = 0

    for ($i = 1; $i -lt $lines.Count; $i++) {
        $line = $lines[$i]

        if ($line -eq '---') {
            $bodyStart = $i + 1
            break
        }

        if ($line -match '^name:') { $hasName = $true }

        if ($line -match '^(name|description|argument-hint|agent|model|tools):') {
            $fields += $line
        }
    }

    $output = @('---')
    if (-not $hasName) { $output += "name: $name" }
    $output += $fields
    $output += '---'
    $output += "<!-- $GeneratedMarker from .claude/skills/$name/SKILL.md -->"
    $output += ''

    if ($bodyStart -lt $lines.Count) {
        $output += $lines[$bodyStart..($lines.Count - 1)]
    }

    Write-GeneratedFile $target $output "copilot prompts/$name.prompt.md"
}

function Generate-CopilotInstructions {
    Get-ChildItem (Join-Path $Src 'rules') -Filter '*.md' -Recurse | ForEach-Object {
        Convert-RuleToInstruction $_
    }
}

function Generate-CopilotPrompts {
    Get-ChildItem (Join-Path $Src 'skills') -Directory | ForEach-Object {
        Convert-SkillToPrompt $_
    }
}

Link-Kind $ClaudeDest claude rules
Link-Kind $ClaudeDest claude skills
Link-Kind (Split-Path -Parent $CopilotSkillsDest) copilot skills
Generate-CopilotInstructions
Generate-CopilotPrompts
